#include "lexer.h"
#include <stdarg.h>

void error_at(int line, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    fprintf(stderr, "error at line %d: ", line);
    vfprintf(stderr, fmt, args);
    fprintf(stderr, "\n");
    va_end(args);
}

static char peek(Lexer *lex) { return lex->source[lex->pos]; }

static char advance(Lexer *lex) {
    char c = lex->source[lex->pos++];
    if (c == '\n') { lex->line++; lex->col = 1; } else { lex->col++; }
    return c;
}

static int is_at_end(Lexer *lex) { return lex->source[lex->pos] == '\0'; }

static void skip_whitespace(Lexer *lex) {
    while (!is_at_end(lex)) {
        char c = peek(lex);
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
            advance(lex);
        } else if (c == '/' && lex->source[lex->pos + 1] == '/') {
            while (!is_at_end(lex) && peek(lex) != '\n') advance(lex);
        } else {
            break;
        }
    }
}

static Token make_token(Lexer *lex, TokenType type, const char *text) {
    Token t;
    t.type = type;
    strncpy(t.text, text, MAX_STRING_LEN - 1);
    t.text[MAX_STRING_LEN - 1] = '\0';
    t.line = lex->line;
    t.col = lex->col;
    t.literal.ival = 0;
    return t;
}

static int add_token(Lexer *lex, Token t) {
    if (lex->token_count >= MAX_TOKENS) { error_at(lex->line, "too many tokens"); return -1; }
    lex->tokens[lex->token_count++] = t;
    return 0;
}

static int lex_number(Lexer *lex) {
    char buf[64]; int i = 0;
    while (!is_at_end(lex) && isdigit(peek(lex))) {
        if (i < 63) buf[i++] = advance(lex); else advance(lex);
    }
    buf[i] = '\0';
    Token t = make_token(lex, TOK_NUM, buf);
    t.literal.ival = strtoll(buf, NULL, 10);
    return add_token(lex, t);
}

static int lex_string(Lexer *lex) {
    advance(lex);
    char buf[MAX_STRING_LEN]; int i = 0;
    while (!is_at_end(lex) && peek(lex) != '"') {
        char c = advance(lex);
        if (c == '\\' && !is_at_end(lex)) {
            // NOTE: escape sequences are not interpreted here; the backslash
            // is copied literally and the following character is emitted as-is.
            if (i < MAX_STRING_LEN - 1) buf[i++] = c;
            c = advance(lex);
        }
        if (i < MAX_STRING_LEN - 1) buf[i++] = c;
    }
    if (is_at_end(lex)) { error_at(lex->line, "unterminated string"); return -1; }
    advance(lex);
    buf[i] = '\0';
    Token t = make_token(lex, TOK_STRING, buf);
    return add_token(lex, t);
}

static int lex_ident(Lexer *lex) {
    char buf[MAX_IDENT_LEN]; int i = 0;
    while (!is_at_end(lex) && (isalnum(peek(lex)) || peek(lex) == '_')) {
        if (i < MAX_IDENT_LEN - 1) buf[i++] = advance(lex); else advance(lex);
    }
    buf[i] = '\0';
    TokenType type = TOK_IDENT;
    if      (strcmp(buf, "if") == 0)       type = TOK_IF;
    else if (strcmp(buf, "else") == 0)     type = TOK_ELSE;
    else if (strcmp(buf, "while") == 0)    type = TOK_WHILE;
    else if (strcmp(buf, "return") == 0)   type = TOK_RETURN;
    else if (strcmp(buf, "fn") == 0)       type = TOK_FN;
    else if (strcmp(buf, "let") == 0)      type = TOK_LET;
    else if (strcmp(buf, "print") == 0)    type = TOK_PRINT;
    else if (strcmp(buf, "true") == 0)     type = TOK_TRUE;
    else if (strcmp(buf, "false") == 0)    type = TOK_FALSE;
    Token t = make_token(lex, type, buf);
    return add_token(lex, t);
}

void lexer_init(Lexer *lex, const char *source) {
    lex->source = source; lex->pos = 0; lex->line = 1; lex->col = 1; lex->token_count = 0;
}

