static ASTNode *parse_unary(Parser *p) {
    if (match(p, TOK_MINUS)) {
        int line = prev(p)->line; ASTNode *operand = parse_unary(p);
        ASTNode *n = ast_alloc(); n->type = NODE_UNARY; n->line = line;
        n->data.unary.op = UNOP_NEG; n->data.unary.operand = operand; return n;
    }
    if (match(p, TOK_NOT)) {
        int line = prev(p)->line; ASTNode *operand = parse_unary(p);
        ASTNode *n = ast_alloc(); n->type = NODE_UNARY; n->line = line;
        n->data.unary.op = UNOP_NOT; n->data.unary.operand = operand; return n;
    }
    return parse_primary(p);
}

static ASTNode *parse_factor(Parser *p) {
    ASTNode *left = parse_unary(p);
    while (match(p, TOK_STAR) || match(p, TOK_SLASH) || match(p, TOK_PERCENT)) {
        int line = prev(p)->line; BinOp op;
        if (prev(p)->type == TOK_STAR) op = OP_MUL;
        else if (prev(p)->type == TOK_SLASH) op = OP_DIV;
        else op = OP_MOD;
        ASTNode *right = parse_unary(p);
        ASTNode *n = ast_alloc(); n->type = NODE_BINOP; n->line = line;
        n->data.binop.op = op; n->data.binop.left = left; n->data.binop.right = right;
        left = n;
    }
    return left;
}

/* NOTE: comparison operators are parsed at a tighter binding than +/-,
   which is buggy: `a + b == c` is parsed as `a + (b == c)` instead of
   `(a + b) == c`. */
static ASTNode *parse_comparison(Parser *p) {
    ASTNode *left = parse_factor(p);
    while (match(p, TOK_EQ) || match(p, TOK_NEQ) || match(p, TOK_LT) ||
           match(p, TOK_GT) || match(p, TOK_LEQ) || match(p, TOK_GEQ)) {
        int line = prev(p)->line; BinOp op;
        switch (prev(p)->type) {
            case TOK_EQ:  op = OP_EQ; break;  case TOK_NEQ: op = OP_NEQ; break;
            case TOK_LT:  op = OP_LT; break;  case TOK_GT:  op = OP_GT; break;
            case TOK_LEQ: op = OP_LEQ; break;  case TOK_GEQ: op = OP_GEQ; break;
            default: op = OP_EQ; break;
        }
        ASTNode *right = parse_factor(p);
        ASTNode *n = ast_alloc(); n->type = NODE_BINOP; n->line = line;
        n->data.binop.op = op; n->data.binop.left = left; n->data.binop.right = right;
        left = n;
    }
    return left;
}

static ASTNode *parse_term(Parser *p) {
    ASTNode *left = parse_comparison(p);
    while (match(p, TOK_PLUS) || match(p, TOK_MINUS)) {
        int line = prev(p)->line;
        BinOp op = (prev(p)->type == TOK_PLUS) ? OP_ADD : OP_SUB;
        ASTNode *right = parse_comparison(p);
        ASTNode *n = ast_alloc(); n->type = NODE_BINOP; n->line = line;
        n->data.binop.op = op; n->data.binop.left = left; n->data.binop.right = right;
        left = n;
    }
    return left;
}

static ASTNode *parse_logic_and(Parser *p) {
    ASTNode *left = parse_term(p);
    while (match(p, TOK_AND)) {
        int line = prev(p)->line; ASTNode *right = parse_term(p);
        ASTNode *n = ast_alloc(); n->type = NODE_BINOP; n->line = line;
        n->data.binop.op = OP_AND; n->data.binop.left = left; n->data.binop.right = right;
        left = n;
    }
    return left;
}

